"""Agent-frozen source interpretations and hand-derived ACTION oracles; no IR.
Agent interpretation, not author validation. Inputs/actions are typed orchestration leaves.
T1-T5 from the author-adjudicated depth cohort apply. Minute calendar grids are declared
per history; strict 'more than' durations use the first integer-second observation after
threshold. Source quotations and provenance are copied from the frozen local corpus.
"""
import csv
from pathlib import Path
S=1000; M=60*S; H=60*M; D=24*H
CASES=[]; STUBS=[]
ROWS={r['corpus_id']:r for r in csv.DictReader(open(Path(__file__).resolve().parents[2]/'corpus_100.csv',encoding='utf-8-sig'))}
def act(n,t,method,args=()): return (t,f'ER{n}.{method}',list(args),f'D{n}')
def ev(n,t,**v): return (t,{f'D{n}.{k}':x for k,x in v.items()})
def hist(name,events,expected,horizon=30*S,kind='nominal',step_ms=S): return dict(name=name,kind=kind,events=events,expected=expected,horizon=horizon,step_ms=step_ms)
def add(n,spec,values,functions,histories,assumptions=(),alternative='',bias='No deliberate simplification beyond stated fixed parameters.',start=0):
 cid=f'E1-{n:03d}'; row=ROWS[cid]
 STUBS.append(dict(id=f'ER{n}',descriptor='[E1 local leaf fixture] '+row['original_text'],values=[dict(id=k,type=t,descriptor=k+' raw input') for k,t in values.items()],functions=[dict(id=k,descriptor=k+' observable leaf command',arguments=[dict(id=a,type=t,descriptor=a) for a,t in args],return_type={'type':'VOID'}) for k,args in functions.items()],enums=[]))
 CASES.append(dict(id=cid,spec=spec,source_text=row['original_text'],source_url=row['source_url'],source_locator=row['source_locator'],source_context=row['source_context'],transcription=['Agent-fixed interpretation; not independently author-validated.','No action automatically changes fixture inputs. Initial inputs are sampled at t=0; rises are later events.',*assumptions],alternative_interpretation=alternative,favorable_bias=bias,devices={f'D{n}':{'category':[f'ER{n}'],'tags':[f'ER{n}']}},stubs=[f'ER{n}: raw typed inputs and observable leaf commands only'],t_start_ms=start,histories=histories))

def duration(n,field,value,duration_ms,method,text,strict=False):
 due=duration_ms+(S if strict else 0)
 add(n,text,{field:'BOOL'},{method:[]},[
 hist('sustained_at_boundary',[ev(n,0,**{field:not value}),ev(n,S,**{field:value})],[act(n,S+due,method)],S+due+2*S),
 hist('reset_then_full_duration',[ev(n,0,**{field:not value}),ev(n,S,**{field:value}),ev(n,duration_ms,**{field:not value}),ev(n,duration_ms+2*S,**{field:value})],[act(n,duration_ms+2*S+due,method)],duration_ms+due+5*S,'reset'),
 hist('negative_short_and_repeat',[ev(n,0,**{field:not value}),ev(n,S,**{field:value}),ev(n,duration_ms,**{field:not value}),ev(n,duration_ms+2*S,**{field:value}),ev(n,duration_ms+due+4*S,**{field:not value}),ev(n,duration_ms+due+6*S,**{field:value})],[act(n,duration_ms+2*S+due,method),act(n,duration_ms+2*due+6*S,method)],duration_ms+2*due+8*S,'repeat')],['Continuous condition; interruption resets elapsed time. One action per qualifying episode; re-arm only after opposite state.','Strict language is tested at the first integer-second sample greater than the threshold.' if strict else 'Threshold is inclusive.'],alternative='Repeated alerts while condition remains true, or fixed delayed action ignoring condition reversal.')
duration(13,'PotPresent',False,5*M,'Off','Turn stove off once when no pot has been present continuously for more than five minutes; reset on pot return.',True)
duration(14,'DoorOpen',True,5*M,'Alarm','Alarm once per door-open episode lasting more than five minutes; closing resets.',True)

def edgecase(n,field,method,text,extra=None,args=(),alternative='A level rule may also act immediately at startup.'):
 values={field:'BOOL',**(extra or {})}
 add(n,text,values,{method:[] if not args else [('Color','STRING')]},[
 hist('rise_once',[ev(n,0,**{field:False}),ev(n,S,**{field:True})],[act(n,S,method,args)]),
 hist('held_initial_no_transition',[ev(n,0,**{field:True})],[],kind='negative'),
 hist('reset_and_repeat',[ev(n,0,**{field:False}),ev(n,S,**{field:True}),ev(n,3*S,**{field:False}),ev(n,5*S,**{field:True})],[act(n,S,method,args),act(n,5*S,method,args)],kind='repeat')],['The trigger is a rising event; a held initial condition is not a new event.'],alternative=alternative)
