def calendar(n,hours,method,spec,weekday=False):
 start=(hours[0]*H)-M
 hs=[hist('first_boundary', [ev(n,0)], [act(n,M,method)],3*M,step_ms=M),hist('repeat_calendar', [ev(n,0)], [act(n,M,method),act(n,(7*D if weekday else D)+M,method)] if len(hours)==1 else [act(n,M,method),act(n,(hours[1]-hours[0])*H+M,method),act(n,D+M,method)],(7*D if weekday else D)+2*M,kind='repeat',step_ms=M),hist('before_boundary',[ev(n,0)],[],0,kind='negative',step_ms=M)]
 add(n,spec,{}, {method:[]},hs,['Week starts Monday. Scheduled commands fire once at the clock boundary. Minute-grid histories retain exact minute boundaries.','Monday is the chosen weekly day.' if weekday else 'Daily recurrence is assumed.'],alternative='A different weekly day.' if weekday else 'A one-off time rather than daily recurrence.',start=start)
