def coffee(n,lo):
 start=lo*H-M if lo else 9*H+59*M
 spec=f'Brew once on initial satisfaction or each false-to-true transition of outside temperature below 40 F and local time in [{lo:02d}:00,10:00).'
 if lo:
  hs=[hist('window_opens_cold',[ev(n,0,TemperatureF=39)],[act(n,M,'Brew')],2*M,step_ms=M),hist('threshold_reset_repeat',[ev(n,0,TemperatureF=40),ev(n,M,TemperatureF=39),ev(n,2*M,TemperatureF=40),ev(n,3*M,TemperatureF=39)],[act(n,M,'Brew'),act(n,3*M,'Brew')],4*M,'repeat',M),hist('warm_and_cutoff',[ev(n,0,TemperatureF=45),ev(n,(10-lo)*H+M,TemperatureF=39)],[],(10-lo)*H+2*M,'boundary',M)]
 else:
  hs=[hist('cold_initial',[ev(n,0,TemperatureF=39)],[act(n,0,'Brew')],2*M),hist('cutoff_excludes',[ev(n,0,TemperatureF=40),ev(n,M,TemperatureF=39)],[],2*M,'boundary'),hist('repeat_inside_window',[ev(n,0,TemperatureF=40),ev(n,S,TemperatureF=39),ev(n,2*S,TemperatureF=40),ev(n,3*S,TemperatureF=39)],[act(n,S,'Brew'),act(n,3*S,'Brew')],2*M,'repeat')]
 add(n,spec,{'TemperatureF':'DOUBLE'},{'Brew':[]},hs,['One action per qualifying episode, not every tick. Cold state at opening starts an episode.'],alternative='Once per day regardless of re-entry, or temperature-event-only triggers.',bias='Episode interpretation chooses recurrence not stated in source.',start=start)
